import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Stock } from '../src/stock.mjs';
import { ReservationBook } from '../src/reservations.mjs';
import { AuditLog } from '../src/audit.mjs';

const MIN = 60_000;
const setup = () => {
  let now = 0;
  const clock = { set: (t) => (now = t) };
  const stock = new Stock([
    { warehouse: 'w1', sku: 'cap', onHand: 6, priority: 1 },
    { warehouse: 'w2', sku: 'cap', onHand: 4, priority: 2 },
  ]);
  const audit = new AuditLog();
  return { clock, stock, audit, book: new ReservationBook(stock, () => now, audit) };
};
const types = (audit) => audit.entries().map((entry) => entry.type);

test('a hold expires exactly at expiresAt', () => {
  const { clock, book } = setup();
  book.reserve({ orderId: 'o1', sku: 'cap', quantity: 2 });
  clock.set(10 * MIN - 1);
  assert.equal(book.available('cap'), 8);
  clock.set(10 * MIN);
  assert.equal(book.available('cap'), 10);
});

test('standard and missing tiers hold for 10 minutes, vip for 30 minutes', () => {
  const { clock, book } = setup();
  clock.set(1000);
  assert.equal(book.reserve({ orderId: 'o1', sku: 'cap', quantity: 1 }).expiresAt, 1000 + 10 * MIN);
  assert.equal(
    book.reserve({ orderId: 'o2', sku: 'cap', quantity: 1, customerTier: 'standard' }).expiresAt,
    1000 + 10 * MIN,
  );
  assert.equal(
    book.reserve({ orderId: 'o3', sku: 'cap', quantity: 1, customerTier: 'gold' }).expiresAt,
    1000 + 10 * MIN,
  );
  assert.equal(
    book.reserve({ orderId: 'o4', sku: 'cap', quantity: 1, customerTier: 'vip' }).expiresAt,
    1000 + 30 * MIN,
  );
});

test('a vip hold keeps stock past 10 minutes and expires at 30', () => {
  const { clock, book } = setup();
  const hold = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 4, customerTier: 'vip' });
  clock.set(29 * MIN);
  assert.equal(book.available('cap'), 6);
  assert.equal(book.commit(hold.id).status, 'committed');

  const other = book.reserve({ orderId: 'o2', sku: 'cap', quantity: 1, customerTier: 'vip' });
  clock.set(29 * MIN + 30 * MIN);
  assert.throws(() => book.commit(other.id), /reservation_expired/);
});

test('releasing twice only releases once', () => {
  const { book, audit } = setup();
  const hold = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 3 });
  book.release(hold.id);
  const again = book.release(hold.id);
  assert.equal(again.status, 'released');
  assert.equal(book.available('cap'), 10);
  assert.deepEqual(types(audit), ['reserved', 'released']);
});

test('releasing a committed or expired reservation changes nothing', () => {
  const { clock, book, stock, audit } = setup();
  const committed = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 3 });
  book.commit(committed.id);
  book.reserve({ orderId: 'o2', sku: 'cap', quantity: 2 });
  assert.equal(book.release(committed.id).status, 'committed');
  assert.equal(stock.level('cap', 'w1').held, 2);
  assert.equal(stock.level('cap', 'w1').onHand, 3);
  assert.equal(book.available('cap'), 5);

  clock.set(10 * MIN);
  const expired = book.release('res_2');
  assert.equal(expired.status, 'expired');
  assert.equal(stock.level('cap', 'w1').held, 0);
  assert.equal(book.available('cap'), 7);
  assert.deepEqual(types(audit), ['reserved', 'committed', 'reserved', 'expired']);
});

test('unknown reservation ids throw reservation_not_found', () => {
  const { book } = setup();
  assert.throws(() => book.release('res_99'), /reservation_not_found/);
  assert.throws(() => book.commit('res_99'), /reservation_not_found/);
});

test('commit expires due holds first and rejects expired reservations', () => {
  const { clock, book, stock, audit } = setup();
  const hold = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 3 });
  clock.set(10 * MIN);
  assert.throws(() => book.commit(hold.id), /reservation_expired/);
  assert.equal(stock.level('cap', 'w1').held, 0);
  assert.equal(stock.level('cap', 'w1').onHand, 6);
  assert.deepEqual(types(audit), ['reserved', 'expired']);
});

test('commit removes quantity from held and onHand; non-held commits throw', () => {
  const { book, stock } = setup();
  const hold = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 8 });
  const committed = book.commit(hold.id);
  assert.equal(committed.status, 'committed');
  assert.deepEqual(
    stock.forSku('cap').map(({ warehouse, onHand, held }) => ({ warehouse, onHand, held })),
    [
      { warehouse: 'w1', onHand: 0, held: 0 },
      { warehouse: 'w2', onHand: 2, held: 0 },
    ],
  );
  assert.throws(() => book.commit(hold.id), /reservation_not_held/);
  const released = book.reserve({ orderId: 'o2', sku: 'cap', quantity: 1 });
  book.release(released.id);
  assert.throws(() => book.commit(released.id), /reservation_not_held/);
});

test('allocation skips quantity already held', () => {
  const { book } = setup();
  book.reserve({ orderId: 'o1', sku: 'cap', quantity: 5 });
  const second = book.reserve({ orderId: 'o2', sku: 'cap', quantity: 3 });
  assert.deepEqual(second.lines, [
    { warehouse: 'w1', quantity: 1 },
    { warehouse: 'w2', quantity: 2 },
  ]);
});

test('reserve cannot oversell: concurrent holds never exceed stock', () => {
  const { book, stock } = setup();
  book.reserve({ orderId: 'o1', sku: 'cap', quantity: 6 });
  book.reserve({ orderId: 'o2', sku: 'cap', quantity: 4 });
  assert.throws(() => book.reserve({ orderId: 'o3', sku: 'cap', quantity: 1 }), /insufficient_stock/);
  for (const level of stock.forSku('cap')) assert.ok(level.held <= level.onHand);
  assert.equal(book.available('cap'), 0);
});

test('reserve is all-or-nothing: shortfall throws insufficient_stock and holds nothing', () => {
  const { book, stock, audit } = setup();
  book.reserve({ orderId: 'o1', sku: 'cap', quantity: 7 });
  assert.throws(() => book.reserve({ orderId: 'o2', sku: 'cap', quantity: 4 }), /insufficient_stock/);
  assert.equal(stock.level('cap', 'w1').held, 6);
  assert.equal(stock.level('cap', 'w2').held, 1);
  assert.equal(book.available('cap'), 3);
  assert.deepEqual(types(audit), ['reserved']);
  assert.throws(() => book.reserve({ orderId: 'o3', sku: 'hat', quantity: 1 }), /insufficient_stock/);

  const next = book.reserve({ orderId: 'o4', sku: 'cap', quantity: 3 });
  assert.equal(next.id, 'res_2');
  assert.equal(next.backorderQuantity, 0);
});

test('reserve returns the documented shape with sequential ids', () => {
  const { clock, book } = setup();
  clock.set(5);
  assert.deepEqual(book.reserve({ orderId: 'o1', sku: 'cap', quantity: 7 }), {
    id: 'res_1',
    orderId: 'o1',
    sku: 'cap',
    lines: [
      { warehouse: 'w1', quantity: 6 },
      { warehouse: 'w2', quantity: 1 },
    ],
    backorderQuantity: 0,
    status: 'held',
    expiresAt: 5 + 10 * MIN,
  });
  assert.equal(book.reserve({ orderId: 'o2', sku: 'cap', quantity: 1 }).id, 'res_2');
});

test('quantities must be positive safe integers', () => {
  const { book, stock } = setup();
  for (const quantity of [0, -1, 1.5, '2', NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, undefined, null])
    assert.throws(() => book.reserve({ orderId: 'o1', sku: 'cap', quantity }), /invalid_quantity/, String(quantity));
  assert.equal(stock.level('cap', 'w1').held, 0);
});

test('orderId and sku must be non-empty strings', () => {
  const { book } = setup();
  for (const request of [
    undefined,
    null,
    {},
    { orderId: '', sku: 'cap', quantity: 1 },
    { orderId: 'o1', sku: '', quantity: 1 },
    { orderId: 1, sku: 'cap', quantity: 1 },
    { orderId: 'o1', sku: ['cap'], quantity: 1 },
  ])
    assert.throws(() => book.reserve(request), /invalid_request/, JSON.stringify(request));
});

test('returned reservations are copies', () => {
  const { book } = setup();
  const hold = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 2 });
  hold.status = 'committed';
  hold.lines[0].quantity = 0;
  hold.expiresAt = 0;
  assert.equal(book.available('cap'), 8);
  const released = book.release(hold.id);
  assert.equal(released.status, 'released');
  assert.deepEqual(released.lines, [{ warehouse: 'w1', quantity: 2 }]);
  assert.equal(book.available('cap'), 10);
});

test('each state change is audited with type, reservationId and time', () => {
  const { clock, book, audit } = setup();
  clock.set(100);
  const a = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 1 });
  const b = book.reserve({ orderId: 'o2', sku: 'cap', quantity: 1 });
  const c = book.reserve({ orderId: 'o3', sku: 'cap', quantity: 1 });
  clock.set(200);
  book.release(a.id);
  clock.set(300);
  book.commit(b.id);
  clock.set(100 + 10 * MIN);
  book.available('cap');
  assert.deepEqual(audit.entries(), [
    { type: 'reserved', reservationId: a.id, at: 100 },
    { type: 'reserved', reservationId: b.id, at: 100 },
    { type: 'reserved', reservationId: c.id, at: 100 },
    { type: 'released', reservationId: a.id, at: 200 },
